private static void runSequence(
        TransitionMode mode,
        int targetNumber,
        AutoTuneManager.Delays delays,
        int modeSlot,
        int... target_slots
) throws InterruptedException {
    TransitionDetector.startAttempt(
            mode,
            targetNumber,
            delays.hubDelay(),
            delays.clickDelay(),
            delays.confirmDelay()
    );

    sendCommand("hub");
    sleep(delays.hubDelay());

    sendCommand("menu");
    sleep(delays.clickDelay());

    clickSlot(modeSlot);
    sleep(delays.clickDelay() + 60L);

    for (int i = 0; i < target_slots.length; i++) {
        clickSlot(target_slots[i]);
        if (i < target_slots.length - 1) {
            sleep(delays.clickDelay() + 60L);
        }
    }
}
